"""生成测试用的虚构产品 PDF（需要 PyMuPDF）。生成结果已随仓库提供，一般无需重跑。

python tests/fixtures/make_fixtures.py
所有公司、产品、条款均为虚构，仅用于测试。
"""
from pathlib import Path

import fitz  # PyMuPDF

HERE = Path(__file__).resolve().parent


def make_pdf(path: Path, pages: list[list[str]]) -> None:
    doc = fitz.open()
    for lines in pages:
        page = doc.new_page(width=595, height=842)
        y = 60
        for ln in lines:
            page.insert_text((50, y), ln, fontname="china-s", fontsize=9.5)
            y += 18
    doc.save(str(path))
    doc.close()


